#include <Adafruit_BME280.h>
Adafruit_BME280 bme;
void setup() { Serial.begin(115200); bme.begin(0x76); }
void loop() {
    Serial.printf("T=%.1f P=%.1f H=%.1f alt=%.1f\n",
        bme.readTemperature(),
        bme.readPressure() / 100.0F,
        bme.readHumidity(),
        bme.readAltitude({{sea_level_hpa}}));
    delay(2000);
}
